/**
 * UK ACCOUNTING PRACTICE QUALITY GATE & INTELLIGENCE VERIFIER
 * Specifically adapted for UK Accounting Practices, Tax Advisers & Bookkeeping Firms
 * 1. Focuses on the MTD for ITSA 2026 hook (£50k+ sole traders & landlords) and 3-minute evening enquiry intake
 * 2. Filters out massive corporate switchboards (0800, 0845, 0870, 0300) so you reach practice partners
 * 3. Normalizes phones to UK standard (+44...)
 * 4. Generates 1-click WhatsApp links for UK mobiles (+447...)
 * 5. Generates consultative call scripts for UK landlines (+441..., +442...)
 * 6. Deduplicates across the batch
 */

const items = $input.all();
const config = $('Edit Fields').first().json || {};
const query = (config.query || 'chartered accountants').trim();
const minReviews = Number(config.min_reviews || 1);
const onlyNoWebsite = Boolean(config.only_no_website === true);

const validatedLeads = [];
const seenPhones = new Set();
const seenNames = new Set();

for (const item of items) {
  const place = item.json || {};
  const businessName = (place.title || place.name || '').trim();
  const rawPhone = (place.phoneNumber || place.phone || '').trim();
  const rawWebsite = (place.website || '').trim();
  const rating = Number(place.rating || 0);
  const reviewsCount = Number(place.ratingCount || place.user_ratings_total || 0);
  const address = (place.address || place.formatted_address || '').trim();
  const category = place.category || place.type || 'Accounting Practice';

  if (!businessName || !rawPhone) continue;
  if (reviewsCount < minReviews) continue;

  // Reject large corporate switchboards & call centres
  const cleanDigits = rawPhone.replace(/[^0-9]/g, '');
  if (
    cleanDigits.startsWith('0800') ||
    cleanDigits.startsWith('0808') ||
    cleanDigits.startsWith('0845') ||
    cleanDigits.startsWith('0870') ||
    cleanDigits.startsWith('0300') ||
    cleanDigits.startsWith('0345') ||
    cleanDigits.startsWith('44800') ||
    cleanDigits.startsWith('44845') ||
    cleanDigits.startsWith('44300')
  ) {
    continue;
  }

  // Normalize phone to E.164 (+44)
  let formattedPhone = rawPhone.replace(/[^0-9+]/g, '');
  if (formattedPhone.startsWith('0')) {
    formattedPhone = '+44' + formattedPhone.substring(1);
  } else if (!formattedPhone.startsWith('+44')) {
    formattedPhone = '+44' + formattedPhone.replace(/^\+/, '');
  }
  const digitsOnly = formattedPhone.replace(/[^0-9]/g, '');

  // Deduplicate across the batch
  const nameKey = businessName.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (seenPhones.has(digitsOnly) || seenNames.has(nameKey)) continue;
  seenPhones.add(digitsOnly);
  seenNames.add(nameKey);

  // Classification & Verification Flag
  let hasWebsite = true;
  let classification = 'has_website';
  let verificationStatus = 'VERIFIED — Live Website Active';

  if (!rawWebsite || rawWebsite === '' || rawWebsite.toLowerCase() === 'none' || rawWebsite.toLowerCase() === 'null') {
    hasWebsite = false;
    classification = 'no_website';
    verificationStatus = 'UNVERIFIED — Google Maps only, verify via LinkedIn/Companies House';
  } else {
    const w = rawWebsite.toLowerCase();
    if (w.includes('facebook.com') || w.includes('linkedin.com') || w.includes('yell.com')) {
      hasWebsite = false;
      classification = 'social_only';
      verificationStatus = 'UNVERIFIED — Social directory only';
    }
  }

  if (onlyNoWebsite && hasWebsite) continue;

  const isMobile = digitsOnly.startsWith('447');
  const channel = isMobile ? 'WhatsApp / SMS' : 'Practice Landline / Partner Call';

  // Dynamic Practice Sandbox Link
  const protoUrl = `https://mercianwealth.com/practices#practice-visualizer?firm=${encodeURIComponent(businessName)}`;

  // Specialized UK Accounting Outreach Copy (MTD 2026 & Evening Intake)
  let stage1Opener = '';
  let stage2Pitch = '';

  if (hasWebsite) {
    // Standard UK practice with existing website
    stage1Opener = `Hi 👋 Came across ${businessName} — quick question: when new sole trader or Ltd Co enquiries land on your website out-of-hours (e.g. 8 PM), how does your team qualify them before booking discovery calls?`;
    stage2Pitch = `In our tests across UK practices, 78% of Ltd Co directors sign with whoever responds first, but standard contact forms take 24–48 hours. At the same time, MTD 2026 quarterly filing is about to multiply manual document chasing across sole traders. We built an interactive practice intake & deadline chasing sandbox showing how ${businessName} can capture clients in 3 minutes with 100% practitioner control: ${protoUrl} — take a look when you have a moment, zero obligation at all.`;
  } else {
    // Sole practitioner or new practice with no dedicated website
    stage1Opener = `Hi 👋 Came across ${businessName} on Google Maps — quick question: do you take all your new sole trader and Ltd Co client enquiries via direct phone / referral, or do you have a dedicated intake page?`;
    stage2Pitch = `With MTD for ITSA landing in 2026 for £50k+ sole traders and landlords, managing client records manually will consume 10+ hours a week. We put together a lightweight practice intake and deadline chasing concept showing how ${businessName} can qualify clients and automate document chasing: ${protoUrl} — take a look whenever you have 30 seconds.`;
  }

  const followUp1 = `Hey — following up on ${businessName}. No pressure at all, just wanted to check if the practice sandbox link landed and see if streamlining intake before MTD 2026 is on your radar.`;
  const followUpFinal = `Last one from me on this — if automating client intake and record chasing isn't an operational priority for ${businessName} right now, that is completely fair. If it ever is, the sandbox remains live at mercianwealth.com/practices. Wishing the practice a smooth quarter!`;

  const waLink = isMobile ? `https://wa.me/${digitsOnly}?text=${encodeURIComponent(stage1Opener)}` : 'N/A';

  // Supabase Payload matching Mercian Wealth schema
  const supabasePayload = {
    name: 'Senior Partner / Practice Director',
    business_name: businessName,
    phone: formattedPhone,
    website: hasWebsite ? rawWebsite : null,
    service_interested: 'Accounting Practice Client Intake & MTD 2026 Deadline Chasing Engine',
    notes: `${address} · ★${rating} (${reviewsCount} reviews) · [${verificationStatus}]`,
    status: 'New',
    source: 'google_maps_accountants',
    lead_type: 'practice',
    local_business_niche: 'Accountant',
    outreach_category: classification,
    outreach_stage: 'uncontacted',
    prototype_url: protoUrl,
    whatsapp_direct_url: isMobile ? waLink : null,
    scraped_metadata: {
      address: address,
      rating: rating,
      reviews_count: reviewsCount,
      trade: 'Accountant',
      channel: channel,
      verification_status: verificationStatus,
      stage_1_opener: stage1Opener,
      stage_2_pitch: stage2Pitch,
      follow_up_1: followUp1,
      follow_up_final: followUpFinal,
      prototype_url: protoUrl
    }
  };

  validatedLeads.push({
    json: {
      "Business Name": businessName,
      "Phone": formattedPhone,
      "Channel": channel,
      "WhatsApp Link": waLink,
      "Reviews": reviewsCount,
      "Rating": rating,
      "Website": rawWebsite || 'None',
      "Address": address,
      "Trade": 'Accountant',
      "Classification": classification,
      "Verification Status": verificationStatus,
      "Stage 1 Opener": stage1Opener,
      "Stage 2 Pitch": stage2Pitch,
      "Follow Up 1": followUp1,
      "Follow Up Final": followUpFinal,
      "Prototype URL": protoUrl,
      "Status": 'New',
      "supabase_payload": supabasePayload
    }
  });
}

return validatedLeads;

