const config = $('2. Pipeline Settings & Channel Config').first().json || {};
const webhookBase = (config.Webhook_Base_URL || 'http://localhost:5678').replace(/\/+$/, '');

const now = new Date();
const todayStr = now.toLocaleDateString('en-CA');

const dueLeads = [];

for (const item of items) {
  const row = item.json || {};
  const leadId = (row['Lead ID'] || '').trim();
  const name = (row['Business Name'] || 'Accounting Practice').trim();
  const niche = (row['Niche'] || 'Accountant').trim();
  const phone = (row['Phone Number'] || '').trim();
  const stage = (row['Current Stage'] || 'Sourced').trim();
  const due = (row['Next Action Due'] || '').trim();
  const protoUrl = (row['Prototype URL'] || `https://mercianwealth.com/practices#practice-visualizer?firm=${encodeURIComponent(name)}`).trim();
  const notes = (row['Notes'] || '').trim();

  if (!leadId || !name) continue;
  if (stage.toLowerCase() === 'won' || stage.toLowerCase() === 'lost') continue;
  if (!due || due > todayStr) continue;

  let stageBadge = '';
  let preDraftedCopy = '';
  let nextStageAction = '';
  let urgencyRank = 2;

  // UK Accountants Niche Master Sequence
  if (stage === 'Sourced') {
    stageBadge = '📊 STAGE 1 OPENER (Evening Intake Hook)';
    urgencyRank = 1;
    nextStageAction = 'Mark Contacted (+2d)';
    preDraftedCopy = `Hi 👋\n\nCame across ${name} — quick question: when new sole trader or Ltd Co enquiries land on your website out-of-hours (e.g. 8 PM), how does your team qualify them before booking discovery calls?`;
  } else if (stage === 'Contacted') {
    stageBadge = '⚡ STAGE 2 (DAY 2 BUMP / SPEED ADVANTAGE)';
    urgencyRank = 1;
    nextStageAction = 'Advance to Follow-up 1 (+2d)';
    preDraftedCopy = `Hey — following up briefly on ${name}. In our practice tests, 78% of Ltd Co directors sign with whoever confirms first, but standard contact forms take 24–48 hours. No pressure at all, just wanted to check if this landed.`;
  } else if (stage === 'Follow-up 1 Due') {
    stageBadge = '✨ STAGE 3 (PRACTICE VISUALIZER & MTD TEASER)';
    urgencyRank = 2;
    nextStageAction = 'Advance to Prototype Follow-up (+2d)';
    preDraftedCopy = `Hey — put together an interactive practice intake & deadline chasing sandbox showing how ${name} can qualify enquiries in 3 minutes and automate record chasing before MTD 2026: ${protoUrl} — take a look when you have a moment, zero obligation at all 👍`;
