    stageBadge = '🎯 STAGE 4 (VISUALIZER 48H FEEDBACK CHECK)';
    urgencyRank = 1;
    nextStageAction = 'Move to Nurture (+30d) - Stop Rule';
    preDraftedCopy = `Hey — did you have a chance to take a look at the practice sandbox (${protoUrl})? Would love to hear your thoughts on whether streamlining intake ahead of MTD 2026 is an operational priority for the team 👀`;
