const query = $input.first().json.query || {};
const leadId = query.id || 'Unknown';
const businessName = query.name || '';
const phone = query.phone || '';
const action = (query.action || 'sent').toLowerCase();
const currentStage = query.stage || 'Sourced';

const now = new Date();
function addDays(days) {
  const d = new Date(now);
  d.setDate(d.getDate() + days);
  return d.toISOString().split('T')[0];
}

let newStage = currentStage;
let nextActionDue = '';
let feedbackMsg = '';

if (action === 'sent') {
  if (currentStage === 'Sourced') {
    newStage = 'Contacted';
    nextActionDue = addDays(2);
    feedbackMsg = 'Stage 1 Opener logged. Follow-up 1 automatically scheduled for ' + nextActionDue + ' (+2 days).';
  } else if (currentStage === 'Contacted') {
    newStage = 'Follow-up 1 Due';
    nextActionDue = addDays(2);
    feedbackMsg = 'Day 2 Bump logged. Value follow-up scheduled for ' + nextActionDue + ' (+2 days).';
  } else if (currentStage === 'Follow-up 1 Due') {
    newStage = 'Nurture';
    nextActionDue = addDays(7);
    feedbackMsg = 'Final value follow-up logged. Moved to Nurture for check-in on ' + nextActionDue + ' (+7 days).';
  } else if (currentStage === 'Prototype Sent') {
